package admin

import "strings"

// iconDataURI 是后台界面用的品牌图标，由 fpk/图标.jpg 派生（见 fpk/make-icons.sh）。
// 内嵌成 data URI 而不是走静态路由：后台在内网/离线环境也要能正常显示图标。
const iconDataURI = "data:image/png;base64,"

const adminHTML = `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<link rel="icon" type="image/png" href="__ICON__">
<title>飞牛影视 Emby 桥接 · 后台</title>
<style>
:root{--glass-bg:rgba(255,255,255,.7);--glass-border:rgba(255,255,255,.8);--glass-shadow:0 8px 32px rgba(31,38,135,.08);--bg-primary:#f5f5f7;--bg-secondary:#fff;--text-primary:#1d1d1f;--text-secondary:#6e6e73;--text-tertiary:#8e8e93;--accent-blue:#0071e3;--accent-green:#34c759;--accent-red:#ff3b30;--input-bg:rgba(255,255,255,.9);--input-border:rgba(0,0,0,.08);--hover-bg:rgba(0,0,0,.03);--log-bg:rgba(245,245,247,.9);--orb-1:rgba(0,113,227,.12);--orb-2:rgba(175,82,222,.1);--orb-3:rgba(52,199,89,.08)}
[data-theme=dark]{--glass-bg:rgba(40,40,42,.7);--glass-border:rgba(255,255,255,.1);--glass-shadow:0 8px 32px rgba(0,0,0,.3);--bg-primary:#000;--bg-secondary:#1c1c1e;--text-primary:#f5f5f7;--text-secondary:#aeaeb2;--text-tertiary:#8e8e93;--accent-blue:#0a84ff;--accent-green:#30d158;--accent-red:#ff453a;--input-bg:rgba(58,58,60,.8);--input-border:rgba(255,255,255,.12);--hover-bg:rgba(255,255,255,.05);--log-bg:rgba(58,58,60,.8);--orb-1:rgba(10,132,255,.18);--orb-2:rgba(191,90,242,.15);--orb-3:rgba(48,209,88,.12)}
*{margin:0;padding:0;box-sizing:border-box}body{background:var(--bg-primary);color:var(--text-primary);min-height:100vh;overflow-x:hidden;position:relative;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","Helvetica Neue","Microsoft YaHei",sans-serif;transition:background .5s,color .5s;-webkit-font-smoothing:antialiased}.bg-orbs{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}.orb{position:absolute;border-radius:50%;filter:blur(100px);animation:float 25s ease-in-out infinite}.orb-1{width:500px;height:500px;background:var(--orb-1);top:-200px;right:-100px}.orb-2{width:400px;height:400px;background:var(--orb-2);bottom:-150px;left:-100px;animation-delay:-8s}.orb-3{width:350px;height:350px;background:var(--orb-3);top:50%;left:40%;animation-delay:-16s}@keyframes float{0%,100%{transform:translate(0,0) scale(1)}33%{transform:translate(40px,-20px) scale(1.05)}66%{transform:translate(-20px,30px) scale(.95)}}.wrap{max-width:1100px;margin:0 auto;padding:28px 24px 40px;position:relative;z-index:1}.top-nav,.panel{background:var(--glass-bg);border:1px solid var(--glass-border);border-radius:20px;box-shadow:var(--glass-shadow);backdrop-filter:blur(40px) saturate(180%);-webkit-backdrop-filter:blur(40px) saturate(180%)}.top-nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;padding:14px 20px}.brand{display:flex;align-items:center;gap:12px}.brand-icon{width:40px;height:40px;background:linear-gradient(135deg,var(--accent-blue),#af52de);border-radius:12px;color:#fff;display:flex;align-items:center;justify-content:center}.brand-icon svg{width:22px;height:22px}.brand-text h1{font-size:19px;font-weight:600;letter-spacing:-.02em}.brand-text .subtitle{font-size:11px;color:var(--text-tertiary);margin-top:1px}.nav-actions{display:flex;align-items:center;gap:10px}.status{padding:5px 12px;font-size:12px;border-radius:999px;background:rgba(120,120,128,.12);color:var(--text-secondary)}.status.ok{background:rgba(52,199,89,.14);color:var(--accent-green)}.status.bad{background:rgba(255,59,48,.14);color:var(--accent-red)}.theme-toggle{width:40px;height:40px;border-radius:12px;border:1px solid var(--input-border);background:var(--input-bg);color:var(--text-primary);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .3s cubic-bezier(.4,0,.2,1)}.theme-toggle:hover{transform:translateY(-1px)}.theme-toggle svg{width:18px;height:18px;transition:transform .5s cubic-bezier(.4,0,.2,1)}.theme-toggle:hover svg{transform:rotate(180deg)}.panel{padding:20px;margin-bottom:20px}.panel-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.panel-title{font-size:16px;font-weight:600;letter-spacing:-.01em}.panel-desc{font-size:12px;color:var(--text-tertiary);margin-top:2px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field label{display:block;font-size:12px;font-weight:500;color:var(--text-secondary);margin-bottom:6px}.field input{width:100%;height:40px;padding:0 14px;border-radius:12px;font-size:13px;border:1px solid var(--input-border);background:var(--input-bg);color:var(--text-primary);outline:none;transition:all .25s}.field input:focus{border-color:var(--accent-blue);box-shadow:0 0 0 3px rgba(0,113,227,.14)}.field input::placeholder{color:var(--text-tertiary)}.form-actions{margin-top:14px;display:flex;justify-content:flex-end}.btn{height:40px;padding:0 16px;border:1px solid var(--input-border);border-radius:12px;background:var(--input-bg);color:var(--text-primary);font-size:13px;font-weight:500;cursor:pointer;transition:all .3s cubic-bezier(.4,0,.2,1)}.btn:hover{transform:translateY(-1px);background:var(--hover-bg)}.btn.primary{background:var(--accent-blue);border-color:transparent;color:#fff}.btn.danger{color:var(--accent-red)}.library{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}.library-card{display:flex;align-items:center;gap:14px;padding:14px;border-radius:18px;border:1px solid var(--input-border);background:var(--bg-secondary);transition:all .3s}.library-card:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(0,0,0,.08)}.poster{width:74px;height:74px;border-radius:14px;object-fit:cover;flex:none;background:var(--log-bg)}.lib-info{flex:1;min-width:0}.lib-name{font-size:14px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lib-meta{font-size:12px;color:var(--text-tertiary);margin:3px 0 10px}.lib-actions{display:flex;gap:8px}.lib-actions input{flex:1;min-width:0;height:34px;padding:0 12px;font-size:12px;border:1px solid var(--input-border);border-radius:10px;background:var(--input-bg);color:var(--text-primary);outline:none}.lib-actions .btn{height:34px;padding:0 10px;font-size:12px;border-radius:10px}.empty{padding:48px;text-align:center;color:var(--text-tertiary);font-size:14px}.auth-card{max-width:390px;margin:14vh auto 0;padding:32px}.auth-brand{display:flex;flex-direction:column;align-items:center;text-align:center;margin-bottom:24px}.auth-brand .brand-icon{width:54px;height:54px;border-radius:18px}.auth-brand h1{font-size:22px;margin-top:14px}.auth-brand p{font-size:13px;color:var(--text-secondary);margin-top:5px}.auth-form .field{margin-bottom:14px}.auth-form .form-actions{justify-content:stretch}.auth-form .btn{width:100%;height:44px}.auth-error{min-height:20px;margin-bottom:12px;font-size:13px;color:var(--accent-red);text-align:center}.hidden{display:none!important}.toast{position:fixed;left:50%;bottom:36px;transform:translateX(-50%) translateY(20px);background:var(--log-bg);border:1px solid var(--input-border);color:var(--text-primary);backdrop-filter:blur(20px);font-size:13px;padding:10px 22px;border-radius:999px;opacity:0;pointer-events:none;transition:all .25s;z-index:100}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}@media(max-width:720px){.wrap{padding:20px 14px 36px}.form-grid{grid-template-columns:1fr}.library{grid-template-columns:1fr}.top-nav{padding:14px}.brand-text .subtitle{display:none}}

/* fork：品牌图标统一由 fpk/图标.jpg 派生（见 fpk/make-icons.sh），不再用内联 SVG */
.brand-icon{background:none;overflow:hidden;box-shadow:0 2px 10px rgba(0,0,0,.16)}
.brand-icon img{width:100%;height:100%;display:block;object-fit:cover}
</style>
</head>
<body>
<div class="bg-orbs"><div class="orb orb-1"></div><div class="orb orb-2"></div><div class="orb orb-3"></div></div>
<div id="loginView" class="wrap hidden">
<div class="panel auth-card">
<div class="auth-brand"><div class="brand-icon"><img src="__ICON__" alt="飞牛影视 Emby 桥接"></div><h1>飞牛影视 Emby 桥接</h1><p>访问桥接配置与媒体库设置</p></div>
<form class="auth-form" id="loginForm">
<div class="field"><label>账号</label><input id="authUser" autocomplete="username" placeholder="admin"></div>
<div class="field"><label>密码</label><input id="authPass" type="password" autocomplete="current-password" placeholder="请输入密码"></div>
<div class="auth-error" id="authError"></div>
<div class="form-actions"><button class="btn primary" type="submit">登录</button></div>
</form>
</div>
</div>
<div id="adminView" class="wrap hidden">
<div class="top-nav">
<div class="brand"><div class="brand-icon"><img src="__ICON__" alt="飞牛影视 Emby 桥接"></div><div class="brand-text"><h1>飞牛影视 Emby 桥接</h1><div class="subtitle">连接配置 · 媒体库美化 · 保存即时生效</div></div></div>
<div class="nav-actions"><span id="connState" class="status"></span><button class="theme-toggle" id="themeToggle" title="切换主题"><svg id="themeIcon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M19 5l-1.5 1.5M6.5 17.5L5 19"/></svg></button></div>
</div>
<div class="panel">
<div class="panel-head"><div><div class="panel-title">飞牛连接</div><div class="panel-desc">修改后先验证连接，成功才切换并保存</div></div><button class="btn danger" id="logout">退出登录</button></div>
<div class="form-grid">
<div class="field"><label>飞牛地址</label><input id="cBase" placeholder="http://192.168.31.189:5666"></div>
<div class="field"><label>飞牛账号</label><input id="cUser" placeholder="admin"></div>
<div class="field" style="grid-column:1/-1"><label>密码</label><input id="cPass" type="password" placeholder="密码（留空=沿用已存）"></div>
</div>
<div class="form-actions"><button class="btn primary" id="cSave">保存并重连</button></div>
</div>
<div class="panel">
<div class="panel-head"><div><div class="panel-title">后台安全</div><div class="panel-desc">自定义访问路径；保存后旧地址立即失效</div></div></div>
<div class="form-grid"><div class="field"><label>后台路径</label><input id="sPath" placeholder="/admin"></div></div>
<div class="form-actions"><button class="btn primary" id="sSave">保存路径</button></div>
</div>
<div class="panel">
<div class="panel-head"><div><div class="panel-title">媒体库图片</div><div class="panel-desc">可用图片 URL，或直接上传本地图片</div></div></div>
<div id="libs" class="library"><div class="empty">加载中…</div></div>
</div>
</div>
<div class="toast" id="toast"></div>
<script>
const $=id=>document.getElementById(id);const API=location.pathname.replace(/\/+$/,'');function toast(m){const t=$('toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2000)}function setTheme(t){document.documentElement.dataset.theme=t;localStorage.setItem('bridge-admin-theme',t);$('themeIcon').innerHTML=t==='dark'?'<path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M19 5l-1.5 1.5M6.5 17.5L5 19"/>'}setTheme(localStorage.getItem('bridge-admin-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));$('themeToggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');function showAdmin(){$('loginView').classList.add('hidden');$('adminView').classList.remove('hidden');loadConn();load();loadSecurity()}function showLogin(){$('adminView').classList.add('hidden');$('loginView').classList.remove('hidden');$('authUser').focus()}async function api(p,o={}){const r=await fetch(p,{...o,headers:{...(o.headers||{})}});if(r.status===401){showLogin();throw new Error('未登录')}return{ok:r.ok,text:await r.text()}}$('loginForm').onsubmit=async e=>{e.preventDefault();$('authError').textContent='';const b=$('loginForm').querySelector('button');b.textContent='登录中…';try{const r=await api(API+'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user:$('authUser').value,pass:$('authPass').value})});if(!r.ok){$('authError').textContent=r.text||'账号或密码错误';return}$('authPass').value='';showAdmin()}finally{b.textContent='登录'}};$('logout').onclick=()=>fetch(API+'/api/logout',{method:'POST'}).finally(showLogin);async function loadConn(){try{const r=await api(API+'/api/connection');const c=JSON.parse(r.text);$('cBase').value=c.base||'';$('cUser').value=c.user||'';const s=$('connState');if(c.ok){s.textContent='已连接 '+(c.token||'');s.className='status ok'}else{s.textContent='未连接';s.className='status bad'}}catch(e){}}$('cSave').onclick=async()=>{const b={base:$('cBase').value.trim(),user:$('cUser').value.trim(),pass:$('cPass').value};if(!b.base||!b.user){toast('地址与账号不能为空');return}$('cSave').textContent='连接中…';const r=await api(API+'/api/connection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});$('cSave').textContent='保存并重连';if(r.ok){toast('已保存并重连成功');$('cPass').value='';loadConn();load()}else toast(r.text||'连接失败')};function imgSrc(l){return l.image?l.image:'/Items/'+l.guid+'/Images/Primary?maxWidth=300&t='+Date.now()}async function save(l,i){const r=await api(API+'/api/lib-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({guid:l.guid,url:i.value.trim()})});if(r.ok){toast(i.value.trim()?'已保存':'已清除');load()}else toast('保存失败')}async function loadSecurity(){try{const r=await api(API+'/api/security');const c=JSON.parse(r.text);$($('sPath')).value=c.admin_path||'/admin'}catch(e){}}$('sSave').onclick=async()=>{const p=$('sPath').value.trim()||'/admin';const r=await api(API+'/api/security',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:p})});if(!r.ok)return toast(r.text||'保存失败');toast('已保存，正在跳转');setTimeout(()=>location.href=JSON.parse(r.text).path,800)};async function load(){try{const r=await api(API+'/api/libs');const ls=JSON.parse(r.text);const b=$('libs');if(!ls.length){b.innerHTML='<div class="empty">没有媒体库</div>';return}b.innerHTML='';for(const l of ls){const c=document.createElement('div');c.className='library-card';const img=document.createElement('img');img.className='poster';img.src=imgSrc(l);const info=document.createElement('div');info.className='lib-info';info.innerHTML='<div class="lib-name"></div><div class="lib-meta"></div>';info.querySelector('.lib-name').textContent=l.name;info.querySelector('.lib-meta').textContent=l.total+' 个条目 · '+(l.image?'已自定义':'默认海报');const row=document.createElement('div');row.className='lib-actions';const input=document.createElement('input');input.type='text';input.placeholder='图片 URL';input.value=l.image||'';const up=document.createElement('button');up.className='btn';up.textContent='上传';const file=document.createElement('input');file.type='file';file.accept='image/jpeg,image/png,image/webp,image/gif';file.style.display='none';up.onclick=()=>file.click();file.onchange=async()=>{if(!file.files[0])return;up.textContent='上传中…';const fd=new FormData();fd.append('guid',l.guid);fd.append('file',file.files[0]);const rr=await api(API+'/api/lib-image/upload',{method:'POST',body:fd});up.textContent='上传';if(rr.ok){toast('已上传并应用');load()}else toast(rr.text||'上传失败')};const btn=document.createElement('button');btn.className='btn primary';btn.textContent='保存';btn.onclick=()=>save(l,input);const clr=document.createElement('button');clr.className='btn';clr.textContent='清除';clr.onclick=()=>{input.value='';save(l,input)};row.append(input,up,btn,clr,file);info.append(row);c.append(img,info);b.append(c)}}catch(e){}}api(API+'/api/session').then(r=>{if(r.ok&&JSON.parse(r.text).ok)showAdmin();else showLogin()}).catch(showLogin);
</script>
</body>
</html>`

// AdminHTML 返回把 __ICON__ 占位符换成内嵌图标的完整后台页面。
func AdminHTML() string {
	return strings.ReplaceAll(adminHTML, "__ICON__", iconDataURI)
}
